use genex::prelude::*;

pub fn wire(game: &mut Game<super::World>) {
    game.on_update(|sim, ctx| {
        if ctx.touches.tapped() || ctx.keys.pressed(Key::Space) {
            sim.world.casts += 1; // the same action from a finger, the mouse (touch 0) or the keyboard
        }
    });
    game.demo("cast", |driver| {
        driver.inject(Input::touch_start(0, 480.0, 270.0).and(Input::touch_end(0, 480.0, 270.0)));
        driver.advance_ms(500);
        json!({ "casts": driver.sim().world.casts })
    });
}
